import{_ as p,H as t,f as F,i}from"./chunks/framework.BH2BK_3i.js";const m=JSON.parse('{"title":"开篇词 | 想快速入门音视频技术，你得这么学","description":"","frontmatter":{},"headers":[{"level":2,"title":"怎样快速进入音视频领域？","slug":"怎样快速进入音视频领域","link":"#怎样快速进入音视频领域","children":[]}],"relativePath":"快手·音视频技术入门课/开篇词｜想快速入门音视频技术，你得这么学.md","filePath":"快手·音视频技术入门课/开篇词｜想快速入门音视频技术，你得这么学.md","lastUpdated":1795556509000}'),l={name:"快手·音视频技术入门课/开篇词｜想快速入门音视频技术，你得这么学.md"};function a(s,e,E,g,n,o){return t(),F("div",null,[...e[0]||(e[0]=[i('<h1 id="开篇词-想快速入门音视频技术-你得这么学" tabindex="-1">开篇词 | 想快速入门音视频技术，你得这么学 <a class="header-anchor" href="#开篇词-想快速入门音视频技术-你得这么学" aria-label="Permalink to &quot;开篇词 | 想快速入门音视频技术，你得这么学&quot;">​</a></h1><p>你好，我是刘歧，江湖人称“大师兄”。目前是快手音视频的首席架构师、FFmpeg 的 GSoC 项目 Mentor，也是《FFmpeg 从入门到精通》一书的作者。</p><p>算到现在，我在互联网行业摸爬滚打已经有 15 年了。可能一部分人对于我的了解就是来自介绍 FFmpeg 的那本书。但其实刚开始我并不是做音视频相关工作的，我做的是机顶盒里图形库的维护，之后也参与过嵌入式平台的 flashplayer 的开发，中途又因为兴趣转技术去做了设备驱动。可能你觉得我走了一些弯路，最后才找到了自己的归属。实则不然，前面的经历都成为了我的积淀与助力。</p><p>也正是因为那次转技术，我才有幸进入这个行业，并在这个行业有了一些发展。所以如果你正在考虑从事这个行业，或想转入这个行业，不要犹豫，现在就是最好的时候。虽说前些年音视频技术都在持续地发展，但近两年疫情的影响导致音视频需求快速上涨，5G 技术又给音视频提供了很好的硬件支持，很多活动转入线上，在线教育、视频会议、电商的直播带货等都迫切地需要音视频技术，所以今后的音视频开发行业充满了无限的可能。</p><h2 id="怎样快速进入音视频领域" tabindex="-1">怎样快速进入音视频领域？ <a class="header-anchor" href="#怎样快速进入音视频领域" aria-label="Permalink to &quot;怎样快速进入音视频领域？&quot;">​</a></h2><p>我们都知道音视频领域需要的知识储备非常庞大，涉及各种音视频基础知识、常用的技术框架、不同的应用场景。所以我们首先要了解音视频领域有哪些基础概念与知识，比如：</p><ul><li><p>什么是 PCM？</p></li><li><p>怎么计算音频的码率？</p></li><li><p>帧率是什么？都有哪些种类？</p></li><li><p>为什么会出现视频播放不了的情况？</p></li><li><p>FFmpeg 有哪些功能？具体应该怎么使用？</p></li><li><p>…</p></li></ul><p>这些音视频技术的基础知识，是所有音视频开发人员都需要掌握的。如果你现在还不是特别清楚，也不用担心，这些问题在我们的专栏里都能找到答案。</p><p>除了这些基础知识之外，如果你想要快速地入门音视频技术，就需要先找到一个突破口。在音视频领域这个突破口非 FFmpeg 莫属，FFmpeg 是音视频平台及音视频系统开发工作中必不可少的一个组件库，也是我们掌握音视频编解码基础知识与流程的重要抓手。如果能够掌握FFmpeg 的用法，那音视频方面的一些基本操作都难不住你。</p><p>但是想要掌握 FFmpeg 是有一定难度的，尤其是刚刚进入这个行业的时候，很有可能被那一千多页的官方文档吓到，所以你可以先听听我是怎么攻克 FFmpeg 这一难题的。</p><p>还记得 2012 我刚开始接触 FFmpeg 时，国内相关的资料非常少，需要自己去查官方文档。但官方文档是一块硬骨头，十分难啃。为了在一周内解决老板交给我的任务，就硬着头皮看下去了，结果在看完帮助文档最开始的一部分以后，我就发现了窍门，比如根据我想实现的功能，按文档索引线索查看就能快速找到对应信息。尽管“啃”官方文档有难度，但通过这样的“锻炼”我不但学到了技术知识，还学会了怎么用好帮助文档。</p><p>后来因为一个契机，我从 2014 年开始给 FFmpeg 项目贡献代码。</p><p>当时我在蓝汛从事 CDN 流媒体服务开发与支持，遇到了一个客户因为使用 FFmpeg 切片时hls_wrap 参数设置得不太合理，导致客户端出现播放卡顿。但客户认为 FFmpeg 支持就是合理的。这时候我的职业操守告诉我一定要解决这个问题，所以我就开始参与到 FFmpeg 社区的交流中，通过不断地给 FFmpeg 解决 bug、添加功能、提交 patch，最后我成为了 FFmpeg的项目维护者，之后我就按照规则删掉了这个 hls_wrap。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" alt=""></a></p><p>就这样，我频繁地在社区中用代码和大家交流，自己也有了很大提升。</p><p>参与 FFmpeg 开源社区的交流能够给我们解决很多问题。因为有些时候我们自己改的代码不一定是最合理的，社区中的能人比较多，思考问题会比较全面，相比自己一个人做 review，质量也会更有保证。所以在这个专栏里我也会教你如何参与到社区的交流中，创建自己专属的模块，乃至成为社区的开发者。相信通过学习你能够很快融入进去，与来自世界各地的开发者进行交流，探索更多的功能，并从中获得最前沿的信息。</p><p>当熟悉了 FFmpeg 之后，你就会发现你在做音视频处理，学习音视频各方面的知识都事半功倍了。因为大多数的知识是相通的，如果你能了解并熟练使用 FFmpeg，那其他的工具对你来说也就不是什么难事了。</p><p>看完我的这些经验，你是不是对自己的学习路径更加清晰了呢？</p><ol><li><p>了解音视频相关基础知识与概念；</p></li><li><p>找到突破点，学会使用 FFmpeg；</p></li><li><p>知识迁移，做到举一反三。</p></li></ol><p>做好这三点，你就能快速地入门音视频技术了。为了帮助你更好地去实施，我会这样来安排这门课程。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.png" alt=""></a></p><ol><li>音视频基础概念</li></ol><p>首先，为了让你对音视频相关的基础概念有一个整体的了解，在专栏的第一部分我会专门讲解音视频相关的参数、视频转码相关的知识、直播行业技术的迭代，扫清你认知上的障碍。这部分是整个专栏的基础，同时也是我们入门音视频技术的一个基础。</p><ol start="2"><li>流媒体技术速成</li></ol><p>然后就到了实际操作应用的部分了，这一部分我会重点介绍几个工具，比如直播推流工具OBS、MP4 专业工具，以及如何通过 FFmpeg 的基本用法深度挖掘 FFmpeg 更多的能力。完成第二部分的学习，你就会对音视频处理的常用工具有一个整体的认识，并且能够掌握如何自助查找 FFmpeg 的帮助信息，获得相关的音视频处理能力。</p><ol start="3"><li>FFmpeg API 应用</li></ol><p>第三部分我会详细解读 FFmpeg 的几个基础模块、关键结构体和常见的应用场景。学完第三部分，你会对 FFmpeg 的 API 接口有一个基本的认识，对 FFmpeg 常用的音视频处理上下文结构体有一个整体的了解，并且能够结合前面两部分内容做一些基本的音视频工具开发。</p><ol start="4"><li>FFmpeg 社区“玩法”</li></ol><p>第四部分我会重点介绍 FFmpeg 开发者常用的工具，FFmpeg 开发者平时参与社区交流的规则，如何为 FFmpeg 添加一个新的模块。之后遇到问题，你就可以参与 FFmpeg 官方社区的交流与讨论，甚至给社区回馈代码了。</p><p>音视频技术相关的工具怎么用，有什么技巧，我都会倾囊相授，为的就是让你少走一些弯路，减轻你的畏难情绪。相信按照这个学习路径一步步学习、实践，你不但会获得独立处理音视频相关操作的能力，还能借鉴专栏里的各种方法做更多探索。扎实的技术基础和解决问题的方法，是我希望通过专栏传递给你的。</p><p>因为音视频行业在持续发展中，各种生活场景逐渐线上化，比如未来的 VR/AR 技术、线上会议、远程看诊等都需要强大的音视频能力的加持；并且音视频技术受疫情、元宇宙、5G 的影响，迭代速度很快，所以就需要我们有自己独立处理开发需求、独立思考探索的能力，主动地去追逐新技术。</p><p>技术迭代的速度也能从侧面展现出行业发展的态势，现在的音视频技术就如同东方冉冉升起的朝阳，会在未来很长一段时间内持续上升，散发光芒。你愿意成为那万丈光芒中的一缕吗？欢迎你加入到音视频开发的领域中，也希望你能够通过这个专栏掌握音视频的基础知识，打开通往音视频技术世界的大门。期待这一个多月的学习之旅，也期待看到你的成长与进步！</p>',32)])])}const A=p(l,[["render",a]]);export{m as __pageData,A as default};
